{
 void ConfigDiagnostics(const UAISenseConfig* Config,TArray<FString>& Errors,TArray<FString>& Warnings)
 {
  if(!Config) { Errors.Add(TEXT("Null sense configuration")); return; } const FString Prefix=Config->GetClass()->GetName()+TEXT(": ");
  if(!Config->GetSenseImplementation()) Errors.Add(Prefix+TEXT("Missing sense implementation"));
  if(!FMath::IsFinite(Config->GetMaxAge()) || Config->GetMaxAge()<0) Errors.Add(Prefix+TEXT("Invalid stimulus max age"));
  auto Range=[&](float V,const TCHAR* Label) { if(!FMath::IsFinite(V) || V<0 || V>1.e8) Errors.Add(Prefix+Label+TEXT(" outside [0,1e8]")); };
  auto Affiliation=[&](const FAISenseAffiliationFilter& Filter) { if(!Filter.bDetectEnemies && !Filter.bDetectFriendlies && !Filter.bDetectNeutrals) Warnings.Add(Prefix+TEXT("All affiliations disabled; no targets will be detected")); };
  if(const auto* Sight=Cast<UAISenseConfig_Sight>(Config)) { Range(Sight->SightRadius,TEXT("SightRadius")); Range(Sight->LoseSightRadius,TEXT("LoseSightRadius")); Range(Sight->PointOfViewBackwardOffset,TEXT("PointOfViewBackwardOffset")); Range(Sight->NearClippingRadius,TEXT("NearClippingRadius")); if(Sight->LoseSightRadius<Sight->SightRadius) Warnings.Add(Prefix+TEXT("LoseSightRadius is smaller than SightRadius")); if(!FMath::IsFinite(Sight->PeripheralVisionAngleDegrees) || Sight->PeripheralVisionAngleDegrees<0 || Sight->PeripheralVisionAngleDegrees>180) Errors.Add(Prefix+TEXT("Peripheral vision half angle outside [0,180]")); Affiliation(Sight->DetectionByAffiliation); }
  if(const auto* Hearing=Cast<UAISenseConfig_Hearing>(Config)) { Range(Hearing->HearingRange,TEXT("HearingRange")); Affiliation(Hearing->DetectionByAffiliation); }
 }
 void WriteDiagnostics(TSharedRef<TJsonWriter<>> J,const UAIPerceptionComponent* C)
 {
  TArray<FString> Errors,Warnings; TSet<UClass*> Senses; int32 Count=0; for(auto It=C->GetSensesConfigIterator();It && Count<64;++It,++Count) { const auto* Config=*It; ConfigDiagnostics(Config,Errors,Warnings); if(Config) { auto* Sense=Config->GetSenseImplementation().Get(); if(Sense && Senses.Contains(Sense)) Errors.Add(TEXT("Multiple configurations for one sense implementation")); if(Sense) Senses.Add(Sense); } }
  if(Count==64) Warnings.Add(TEXT("Configuration diagnostics capped at 64 senses")); if(C->GetDominantSense() && !Senses.Contains(C->GetDominantSense().Get())) Warnings.Add(TEXT("Dominant sense has no configuration"));
  J->WriteObjectStart(TEXT("validation")); J->WriteValue(TEXT("valid"),Errors.IsEmpty()); J->WriteArrayStart(TEXT("errors")); for(const auto& Error:Errors) J->WriteValue(Error); J->WriteArrayEnd(); J->WriteArrayStart(TEXT("warnings")); for(const auto& Warning:Warnings) J->WriteValue(Warning); J->WriteArrayEnd(); J->WriteObjectEnd();
 }
}
static FString InspectPerception(const FString& ComponentPath,const FString& Search,int32 Limit,int32 PIEInstance,bool Editor)
{
 auto* World=NavigationWorldUtils::Resolve(Editor ? TEXT("editor") : TEXT("pie"),PIEInstance);
 if(!IsInGameThread() || !IsValid(World) || World->WorldType!=(Editor ? EWorldType::Editor : EWorldType::PIE) || World->bIsTearingDown) throw std::runtime_error("Perception inspection requires selected live editor/PIE world on game thread");
 if(Limit<1 || Limit>256 || Search.Len()>128 || ComponentPath.Len()>2048) throw std::runtime_error("Perception inspection bounds exceeded");
 TArray<UAIPerceptionComponent*> Components; for(TObjectIterator<UAIPerceptionComponent> It;It;++It) if(IsValid(*It) && !It->IsTemplate() && It->GetWorld()==World && It->GetOwner() && (ComponentPath.IsEmpty() || It->GetPathName()==ComponentPath) && (Search.IsEmpty() || It->GetPathName().Contains(Search))) Components.Add(*It);
 if(!ComponentPath.IsEmpty() && Components.IsEmpty()) throw std::runtime_error("Perception component not found in selected world"); Components.Sort([](const auto& A,const auto& B) { return A.GetPathName()<B.GetPathName(); });
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("world"),World->GetPathName()); J->WriteValue(TEXT("context"),Editor ? TEXT("editor") : TEXT("pie")); J->WriteValue(TEXT("total"),Components.Num()); J->WriteValue(TEXT("truncated"),Components.Num()>Limit); J->WriteArrayStart(TEXT("components"));
 for(int32 Index=0;Index<FMath::Min(Limit,Components.Num());++Index) { auto* C=Components[Index]; J->WriteObjectStart(); J->WriteValue(TEXT("component_path"),C->GetPathName()); J->WriteValue(TEXT("owner_path"),C->GetOwner()->GetPathName()); J->WriteValue(TEXT("package"),C->GetOwner()->GetPackage()->GetName()); J->WriteValue(TEXT("dirty"),C->GetOwner()->GetPackage()->IsDirty()); J->WriteValue(TEXT("registered"),C->IsRegistered()); J->WriteValue(TEXT("active"),C->IsActive()); J->WriteValue(TEXT("authority"),C->GetOwner()->HasAuthority()); J->WriteValue(TEXT("dominant_sense"),GetPathNameSafe(C->GetDominantSense().Get()));
 WriteDiagnostics(J,C); J->WriteArrayStart(TEXT("senses")); int32 SenseCount=0; for(auto It=C->GetSensesConfigIterator();It && SenseCount<64;++It,++SenseCount) if(const auto* Config=*It) { J->WriteObjectStart(); J->WriteValue(TEXT("config_class"),Config->GetClass()->GetPathName()); J->WriteValue(TEXT("sense_class"),GetPathNameSafe(Config->GetSenseImplementation().Get())); J->WriteValue(TEXT("max_age"),Config->GetMaxAge()); J->WriteValue(TEXT("starts_enabled"),Config->GetStartsEnabled()); J->WriteValue(TEXT("enabled_state_available"),!Editor); if(!Editor) J->WriteValue(TEXT("enabled"),C->IsSenseEnabled(Config->GetSenseImplementation())); J->WriteObjectStart(TEXT("properties")); int32 Fields=0; for(TFieldIterator<FProperty> Field(Config->GetClass());Field && Fields<128;++Field) if(Field->HasAnyPropertyFlags(CPF_Edit) && !Field->HasAnyPropertyFlags(CPF_Transient)) { ++Fields; FString Text; Field->ExportTextItem_Direct(Text,Field->ContainerPtrToValuePtr<void>(Config),nullptr,nullptr,PPF_None); J->WriteValue(Field->GetName(),Text.Left(4096)); } J->WriteObjectEnd(); J->WriteValue(TEXT("properties_capped"),Fields==128); J->WriteObjectEnd(); } J->WriteArrayEnd(); J->WriteValue(TEXT("senses_capped"),SenseCount==64);
 TArray<AActor*> Actors; if(!Editor) C->GetKnownPerceivedActors(nullptr,Actors); Actors.RemoveAll([](const AActor* Actor) { return !IsValid(Actor); }); Actors.Sort([](const AActor& A,const AActor& B) { return A.GetPathName()<B.GetPathName(); }); J->WriteValue(TEXT("known_actor_count"),Actors.Num()); J->WriteValue(TEXT("actors_truncated"),Actors.Num()>256); J->WriteArrayStart(TEXT("actors"));
 for(int32 ActorIndex=0;ActorIndex<FMath::Min(Actors.Num(),256);++ActorIndex) { FActorPerceptionBlueprintInfo Info; if(!C->GetActorsPerception(Actors[ActorIndex],Info)) continue; J->WriteObjectStart(); J->WriteValue(TEXT("actor_path"),Actors[ActorIndex]->GetPathName()); J->WriteValue(TEXT("hostile"),bool(Info.bIsHostile)); J->WriteValue(TEXT("friendly"),bool(Info.bIsFriendly)); J->WriteArrayStart(TEXT("stimuli")); for(int32 StimulusIndex=0;StimulusIndex<FMath::Min(Info.LastSensedStimuli.Num(),64);++StimulusIndex) { const auto& Stimulus=Info.LastSensedStimuli[StimulusIndex]; J->WriteObjectStart(); J->WriteValue(TEXT("sense_index"),StimulusIndex); J->WriteValue(TEXT("valid"),Stimulus.IsValid()); J->WriteValue(TEXT("active"),Stimulus.IsActive()); J->WriteValue(TEXT("sensed"),Stimulus.WasSuccessfullySensed()); J->WriteValue(TEXT("expired"),Stimulus.IsExpired()); J->WriteValue(TEXT("age"),Stimulus.GetAge()); J->WriteValue(TEXT("strength"),Stimulus.Strength); J->WriteValue(TEXT("tag"),Stimulus.Tag.ToString()); J->WriteValue(TEXT("stimulus_location"),Stimulus.StimulusLocation.ToString()); J->WriteValue(TEXT("receiver_location"),Stimulus.ReceiverLocation.ToString()); J->WriteObjectEnd(); } J->WriteArrayEnd(); J->WriteValue(TEXT("stimuli_truncated"),Info.LastSensedStimuli.Num()>64); J->WriteObjectEnd(); }
 J->WriteArrayEnd(); J->WriteObjectEnd(); } J->WriteArrayEnd(); J->WriteObjectEnd(); J->Close(); return Result;
}

FString PerceptionUtils::InspectRuntime(const FString& Path,const FString& Search,int32 Limit,int32 PIE) { return InspectPerception(Path,Search,Limit,PIE,false); }
FString PerceptionUtils::InspectEditor(const FString& Path,const FString& Search,int32 Limit) { return InspectPerception(Path,Search,Limit,-1,true); }

static FString ControlPerception(const FPerceptionReq& R,bool Editor)
{
 auto* World=NavigationWorldUtils::Resolve(Editor ? TEXT("editor") : TEXT("pie"),R.PIEInstance); if(!IsInGameThread() || !IsValid(World) || World->WorldType!=(Editor ? EWorldType::Editor : EWorldType::PIE) || World->bIsTearingDown) throw std::runtime_error("Perception control requires selected live world on game thread");
 if(Editor && (!GEditor || GEditor->PlayWorld || (R.Operation!=TEXT("configure") && R.Operation!=TEXT("dominant")))) throw std::runtime_error("Editor configuration requires stopped PIE and configure/dominant operation");
 if(R.ComponentPath.IsEmpty() || R.ComponentPath.Len()>2048 || R.ActorPath.Len()>2048 || R.SenseClassPath.Len()>1024) throw std::runtime_error("Perception control requires bounded explicit paths");
 auto* C=FindObject<UAIPerceptionComponent>(nullptr,*R.ComponentPath); if(!IsValid(C) || C->IsTemplate() || C->GetWorld()!=World || !C->IsRegistered() || !C->GetOwner() || !C->GetOwner()->HasAuthority()) throw std::runtime_error("Perception control requires a registered authoritative component in selected PIE world");
 if(Editor && (!C->GetOwner()->GetPackage()->GetName().StartsWith(TEXT("/Game/")) || C->GetOwner()->HasAnyFlags(RF_Transient) || C->GetOwner()->GetWorld()!=World)) throw std::runtime_error("Persistent configuration requires a placed actor in a /Game editor world");
 bool Change=true; UClass* Sense=nullptr; AActor* Actor=nullptr;
 TStrongObjectPtr<UAISenseConfig> Prepared;
 if(R.Operation==TEXT("configure")) {
  if(R.ConfigClassPath.Len()>1024 || R.Properties.Num()>64) throw std::runtime_error("Sense config requires bounded class path and <=64 fields"); auto* Class=FindObject<UClass>(nullptr,*R.ConfigClassPath); if(!Class || !Class->IsChildOf(UAISenseConfig::StaticClass()) || Class->HasAnyClassFlags(CLASS_Abstract|CLASS_Deprecated|CLASS_NewerVersionExists)) throw std::runtime_error("Config requires loaded concrete native sense config class");
  const UAISenseConfig* Existing=nullptr; for(auto It=C->GetSensesConfigIterator();It;++It) if(*It && (*It)->GetClass()==Class) Existing=*It;
  Prepared.Reset(Existing ? DuplicateObject<UAISenseConfig>(Existing,GetTransientPackage()) : NewObject<UAISenseConfig>(GetTransientPackage(),Class));
  TFunction<bool(FProperty*,int32)> Plain=[&](FProperty* P,int32 Depth) { if(Depth>4 || P->ArrayDim!=1) return false; if(CastField<FNumericProperty>(P) || CastField<FBoolProperty>(P) || CastField<FEnumProperty>(P)) return true; if(auto* Struct=CastField<FStructProperty>(P)) { for(TFieldIterator<FProperty> It(Struct->Struct);It;++It) if(!Plain(*It,Depth+1)) return false; return true; } return false; };
  TFunction<void(FProperty*,void*)> Validate=[&](FProperty* P,void* Address) { if(auto* N=CastField<FNumericProperty>(P)) { const double V=N->IsFloatingPoint() ? N->GetFloatingPointPropertyValue(Address) : double(N->GetSignedIntPropertyValue(Address)); if(!FMath::IsFinite(V) || FMath::Abs(V)>1.e8 || (P->HasMetaData(TEXT("ClampMin")) && V<FCString::Atod(*P->GetMetaData(TEXT("ClampMin")))) || (P->HasMetaData(TEXT("ClampMax")) && V>FCString::Atod(*P->GetMetaData(TEXT("ClampMax"))))) throw std::runtime_error("Sense numeric setting exceeds native bounds"); } if(auto* E=CastField<FEnumProperty>(P)) if(!E->GetEnum()->IsValidEnumValue(E->GetUnderlyingProperty()->GetSignedIntPropertyValue(Address))) throw std::runtime_error("Invalid sense enum value"); if(auto* S=CastField<FStructProperty>(P)) for(TFieldIterator<FProperty> It(S->Struct);It;++It) Validate(*It,It->ContainerPtrToValuePtr<void>(Address)); };
  Change=!Existing; for(const auto& Pair:R.Properties) { auto* P=FindFProperty<FProperty>(Class,*Pair.Key); if(!P || !P->HasAnyPropertyFlags(CPF_Edit) || P->HasAnyPropertyFlags(CPF_Transient|CPF_EditConst|CPF_Deprecated) || !Plain(P,0) || Pair.Value.Len()>4096) throw std::runtime_error("Config settings require editable numeric/bool/enum/plain-struct fields"); auto* Address=P->ContainerPtrToValuePtr<void>(Prepared.Get()); FStringOutputDevice Errors; const auto* End=P->ImportText_Direct(*Pair.Value,Address,Prepared.Get(),PPF_None,&Errors); if(!End || !Errors.IsEmpty() || !FString(End).TrimStartAndEnd().IsEmpty()) throw std::runtime_error("Native sense config import failed"); Validate(P,Address); if(Existing) Change|=!P->Identical(Address,P->ContainerPtrToValuePtr<void>(Existing),PPF_None); }
  TArray<FString> ConfigErrors,ConfigWarnings; ConfigDiagnostics(Prepared.Get(),ConfigErrors,ConfigWarnings); if(!ConfigErrors.IsEmpty()) throw std::runtime_error(TCHAR_TO_UTF8(*FString::Join(ConfigErrors,TEXT("; "))));
  Sense=Prepared->GetSenseImplementation().Get(); for(auto It=C->GetSensesConfigIterator();It;++It) if(*It && (*It)->GetSenseImplementation().Get()==Sense && (*It)->GetClass()!=Class) throw std::runtime_error("A different config class already owns this sense; edit that config explicitly"); if(!Sense || !Sense->IsChildOf(UAISense::StaticClass())) throw std::runtime_error("Sense config has no native implementation"); if(!Existing && !R.bConfirm) throw std::runtime_error("Adding a listener sense requires confirmation");
 }

 else if(R.Operation==TEXT("sense") || R.Operation==TEXT("dominant")) { Sense=FindObject<UClass>(nullptr,*R.SenseClassPath); if(!Sense || !Sense->IsChildOf(UAISense::StaticClass()) || Sense->HasAnyClassFlags(CLASS_Abstract|CLASS_Deprecated|CLASS_NewerVersionExists)) throw std::runtime_error("Sense control requires a loaded concrete sense class"); bool Configured=false; for(auto It=C->GetSensesConfigIterator();It;++It) if(*It && (*It)->GetSenseImplementation()==Sense) Configured=true; if(!Configured) throw std::runtime_error("Sense is not configured on selected listener"); Change=R.Operation==TEXT("dominant") ? C->GetDominantSense().Get()!=Sense : C->IsSenseEnabled(Sense)!=R.bEnabled; }
 else if(R.Operation==TEXT("forget_actor")) { if(!R.bConfirm) throw std::runtime_error("Forgetting perception requires confirmation"); Actor=FindObject<AActor>(nullptr,*R.ActorPath); if(!IsValid(Actor) || Actor->GetWorld()!=World) throw std::runtime_error("Actor must belong to selected PIE world"); FActorPerceptionBlueprintInfo Info; Change=C->GetActorsPerception(Actor,Info); }
 else if(R.Operation==TEXT("forget_all")) { if(!R.bConfirm) throw std::runtime_error("Forgetting all perception requires confirmation"); TArray<AActor*> Known; C->GetKnownPerceivedActors(nullptr,Known); Change=!Known.IsEmpty(); }
 else if(R.Operation!=TEXT("refresh")) throw std::runtime_error("Operation requires configure, sense, dominant, refresh, forget_actor or forget_all");
 TUniquePtr<FScopedTransaction> Transaction; if(Editor && Change && !R.bDryRun) { Transaction=MakeUnique<FScopedTransaction>(FText::FromString(TEXT("MCP Configure AI Perception"))); C->GetOwner()->Modify(); C->SetFlags(RF_Transactional); C->Modify(); for(auto It=C->GetSensesConfigIterator();It;++It) if(*It) { auto* Config=const_cast<UAISenseConfig*>(*It); Config->SetFlags(RF_Transactional); Config->Modify(); } }
 if(Change && !R.bDryRun) { if(R.Operation==TEXT("configure")) { auto* Config=DuplicateObject<UAISenseConfig>(Prepared.Get(),C); if(Editor) Config->SetFlags(RF_Transactional); C->ConfigureSense(*Config); C->RequestStimuliListenerUpdate(); } else if(R.Operation==TEXT("dominant")) { C->SetDominantSense(Sense); C->RequestStimuliListenerUpdate(); } else if(R.Operation==TEXT("sense")) C->SetSenseEnabled(Sense,R.bEnabled); else if(R.Operation==TEXT("refresh")) C->RequestStimuliListenerUpdate(); else if(Actor) C->ForgetActor(Actor); else C->ForgetAll(); }
 if(Editor && Change && !R.bDryRun) { C->PostEditChange(); C->MarkPackageDirty(); } Transaction.Reset(); bool Saved=false; if(Editor && R.bSave && !R.bDryRun) { Saved=UEditorLoadingAndSavingUtils::SavePackages({C->GetOwner()->GetPackage()},false); if(!Saved) throw std::runtime_error("Perception configuration applied but actor package save failed"); }
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("component_path"),C->GetPathName()); J->WriteValue(TEXT("operation"),R.Operation); J->WriteValue(TEXT("persistent"),Editor); J->WriteValue(TEXT("saved"),Saved); J->WriteValue(TEXT("would_change"),Change); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("applied"),Change && !R.bDryRun); if(Sense) J->WriteValue(TEXT("sense_enabled"),C->IsSenseEnabled(Sense)); J->WriteValue(TEXT("dominant_sense"),GetPathNameSafe(C->GetDominantSense().Get())); J->WriteObjectEnd(); J->Close(); return Result;
}

FString PerceptionUtils::ControlRuntime(const FPerceptionReq& R) { return ControlPerception(R,false); }
FString PerceptionUtils::ControlEditor(const FPerceptionReq& R) { return ControlPerception(R,true); }

FString PerceptionUtils::ReportNoise(const FPerceptionReq& R)
{
 auto* World=NavigationWorldUtils::Resolve(TEXT("pie"),R.PIEInstance); if(!IsInGameThread() || !IsValid(World) || World->WorldType!=EWorldType::PIE || World->bIsTearingDown || !UAIPerceptionSystem::GetCurrent(World)) throw std::runtime_error("Noise reporting requires live PIE with native perception system");
 if(R.ActorPath.IsEmpty() || R.ActorPath.Len()>2048 || R.Tag.Len()>128 || !FMath::IsFinite(R.Loudness) || R.Loudness<=0 || R.Loudness>1000 || !FMath::IsFinite(R.MaxRange) || R.MaxRange<0 || R.MaxRange>1.e7) throw std::runtime_error("Noise requires explicit source, bounded tag, loudness (0,1000] and range [0,1e7]");
 auto* Actor=FindObject<AActor>(nullptr,*R.ActorPath); if(!IsValid(Actor) || Actor->IsTemplate() || Actor->GetWorld()!=World || !Actor->HasAuthority()) throw std::runtime_error("Noise source must be authoritative actor in selected PIE world"); const FVector Location=R.bUseActorLocation ? Actor->GetActorLocation() : R.Location; if(Location.ContainsNaN() || FMath::Abs(Location.X)>1.e8 || FMath::Abs(Location.Y)>1.e8 || FMath::Abs(Location.Z)>1.e8) throw std::runtime_error("Noise location exceeds finite world bounds");
 if(!R.bDryRun) UAISense_Hearing::ReportNoiseEvent(World,Location,R.Loudness,Actor,R.MaxRange,FName(*R.Tag));
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("world"),World->GetPathName()); J->WriteValue(TEXT("source_actor"),Actor->GetPathName()); J->WriteValue(TEXT("location"),Location.ToString()); J->WriteValue(TEXT("loudness"),R.Loudness); J->WriteValue(TEXT("max_range"),R.MaxRange); J->WriteValue(TEXT("tag"),R.Tag); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("submitted"),!R.bDryRun); J->WriteValue(TEXT("delivery"),TEXT("Native asynchronous hearing event; reception depends on listener configuration, range and affiliation.")); J->WriteObjectEnd(); J->Close(); return Result;
}

FString PerceptionUtils::Discover(const FString& Search,int32 Limit)
{
 if(!IsInGameThread() || Search.Len()>128 || Limit<1 || Limit>256) throw std::runtime_error("Perception discovery requires game thread, search <=128 and limit 1-256");
 TArray<UClass*> Configs,Senses; for(TObjectIterator<UClass> It;It;++It) { auto* Class=*It; if(Class->HasAnyClassFlags(CLASS_Abstract|CLASS_Deprecated|CLASS_NewerVersionExists) || Class->GetName().StartsWith(TEXT("SKEL_")) || Class->GetName().StartsWith(TEXT("REINST_")) || (!Search.IsEmpty() && !Class->GetPathName().Contains(Search))) continue; if(Class->IsChildOf(UAISenseConfig::StaticClass())) Configs.Add(Class); else if(Class->IsChildOf(UAISense::StaticClass())) Senses.Add(Class); }
 auto Sort=[](const UClass& A,const UClass& B) { return A.GetPathName()<B.GetPathName(); }; Configs.Sort(Sort); Senses.Sort(Sort);
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("scope"),TEXT("Loaded concrete sense/config classes and reflected editable defaults; optional unloaded modules are not enumerated.")); J->WriteValue(TEXT("config_total"),Configs.Num()); J->WriteValue(TEXT("configs_truncated"),Configs.Num()>Limit); J->WriteArrayStart(TEXT("configs"));
 for(int32 Index=0;Index<FMath::Min(Configs.Num(),Limit);++Index) { auto* Class=Configs[Index]; const auto* Config=Class->GetDefaultObject<UAISenseConfig>(); J->WriteObjectStart(); J->WriteValue(TEXT("class_path"),Class->GetPathName()); J->WriteValue(TEXT("sense_class"),GetPathNameSafe(Config->GetSenseImplementation().Get())); J->WriteValue(TEXT("display_name"),Class->GetDisplayNameText().ToString()); J->WriteArrayStart(TEXT("properties")); int32 Count=0; for(TFieldIterator<FProperty> It(Class);It && Count<128;++It) if(It->HasAnyPropertyFlags(CPF_Edit) && !It->HasAnyPropertyFlags(CPF_Transient)) { ++Count; J->WriteObjectStart(); J->WriteValue(TEXT("name"),It->GetName()); J->WriteValue(TEXT("type"),It->GetCPPType()); J->WriteValue(TEXT("read_only"),It->HasAnyPropertyFlags(CPF_EditConst)); J->WriteValue(TEXT("category"),It->GetMetaData(TEXT("Category"))); J->WriteValue(TEXT("clamp_min"),It->GetMetaData(TEXT("ClampMin"))); J->WriteValue(TEXT("clamp_max"),It->GetMetaData(TEXT("ClampMax"))); FString Value; It->ExportTextItem_Direct(Value,It->ContainerPtrToValuePtr<void>(Config),nullptr,nullptr,PPF_None); J->WriteValue(TEXT("default"),Value.Left(4096)); J->WriteValue(TEXT("default_truncated"),Value.Len()>4096); J->WriteObjectEnd(); } J->WriteArrayEnd(); J->WriteValue(TEXT("properties_capped"),Count==128); J->WriteObjectEnd(); }
 J->WriteArrayEnd(); J->WriteValue(TEXT("sense_total"),Senses.Num()); J->WriteValue(TEXT("senses_truncated"),Senses.Num()>Limit); J->WriteArrayStart(TEXT("senses")); for(int32 Index=0;Index<FMath::Min(Senses.Num(),Limit);++Index) { J->WriteObjectStart(); J->WriteValue(TEXT("class_path"),Senses[Index]->GetPathName()); J->WriteValue(TEXT("display_name"),Senses[Index]->GetDisplayNameText().ToString()); J->WriteObjectEnd(); } J->WriteArrayEnd(); J->WriteObjectEnd(); J->Close(); return Result;
}

FString PerceptionUtils::ReportDamage(const FPerceptionReq& R)
{
 auto* World=NavigationWorldUtils::Resolve(TEXT("pie"),R.PIEInstance); if(!IsInGameThread() || !IsValid(World) || World->WorldType!=EWorldType::PIE || World->bIsTearingDown || !UAIPerceptionSystem::GetCurrent(World)) throw std::runtime_error("Damage reporting requires live PIE with perception system");
 if(R.ActorPath.IsEmpty() || R.InstigatorPath.IsEmpty() || R.ActorPath.Len()>2048 || R.InstigatorPath.Len()>2048 || R.Tag.Len()>128 || !FMath::IsFinite(R.DamageAmount) || R.DamageAmount<=0 || R.DamageAmount>1.e8) throw std::runtime_error("Damage stimulus requires explicit actor paths, bounded tag and amount (0,1e8]");
 auto Resolve=[&](const FString& Path) { auto* Actor=FindObject<AActor>(nullptr,*Path); if(!IsValid(Actor) || Actor->IsTemplate() || Actor->GetWorld()!=World || !Actor->HasAuthority()) throw std::runtime_error("Damage stimulus actors must be authoritative in selected PIE world"); return Actor; }; auto* Damaged=Resolve(R.ActorPath); auto* Instigator=Resolve(R.InstigatorPath);
 const FVector EventLocation=R.bUseActorLocation ? Instigator->GetActorLocation() : R.Location; const FVector HitLocation=R.bUseActorLocation ? Damaged->GetActorLocation() : R.HitLocation; auto Valid=[](const FVector& V) { return !V.ContainsNaN() && FMath::Abs(V.X)<=1.e8 && FMath::Abs(V.Y)<=1.e8 && FMath::Abs(V.Z)<=1.e8; }; if(!Valid(EventLocation) || !Valid(HitLocation)) throw std::runtime_error("Damage stimulus locations exceed finite world bounds");
 if(!R.bDryRun) UAISense_Damage::ReportDamageEvent(World,Damaged,Instigator,R.DamageAmount,EventLocation,HitLocation,FName(*R.Tag));
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("world"),World->GetPathName()); J->WriteValue(TEXT("damaged_actor"),Damaged->GetPathName()); J->WriteValue(TEXT("instigator"),Instigator->GetPathName()); J->WriteValue(TEXT("amount"),R.DamageAmount); J->WriteValue(TEXT("event_location"),EventLocation.ToString()); J->WriteValue(TEXT("hit_location"),HitLocation.ToString()); J->WriteValue(TEXT("tag"),R.Tag); J->WriteValue(TEXT("submitted"),!R.bDryRun); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("delivery"),TEXT("Native asynchronous perception event only; actor health/damage callbacks are not changed.")); J->WriteObjectEnd(); J->Close(); return Result;
}

FString PerceptionUtils::ControlSource(const FPerceptionReq& R)
{
 auto* World=NavigationWorldUtils::Resolve(TEXT("pie"),R.PIEInstance); if(!IsInGameThread() || !IsValid(World) || World->WorldType!=EWorldType::PIE || World->bIsTearingDown) throw std::runtime_error("Source control requires live PIE on game thread"); auto* System=UAIPerceptionSystem::GetCurrent(World); if(!System) throw std::runtime_error("Selected world has no perception system");
 if(R.ActorPath.IsEmpty() || R.ActorPath.Len()>2048 || R.SenseClassPath.IsEmpty() || R.SenseClassPath.Len()>1024) throw std::runtime_error("Source control requires bounded explicit actor/sense paths"); auto* Actor=FindObject<AActor>(nullptr,*R.ActorPath); if(!IsValid(Actor) || Actor->IsTemplate() || Actor->GetWorld()!=World || !Actor->HasAuthority()) throw std::runtime_error("Source actor must be authoritative in selected PIE world");
 auto* Sense=FindObject<UClass>(nullptr,*R.SenseClassPath); if(!Sense || !Sense->IsChildOf(UAISense::StaticClass()) || Sense->HasAnyClassFlags(CLASS_Abstract|CLASS_Deprecated|CLASS_NewerVersionExists)) throw std::runtime_error("Source control requires loaded concrete sense class"); if(R.Operation!=TEXT("register") && R.Operation!=TEXT("unregister")) throw std::runtime_error("Source operation requires register or unregister"); if(R.Operation==TEXT("unregister") && !R.bConfirm) throw std::runtime_error("Unregistering a stimulus source requires confirmation");
 if(!R.bDryRun) { if(R.Operation==TEXT("register")) System->RegisterSourceForSenseClass(Sense,*Actor); else System->UnregisterSource(*Actor,Sense); }
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("world"),World->GetPathName()); J->WriteValue(TEXT("actor_path"),Actor->GetPathName()); J->WriteValue(TEXT("sense_class"),Sense->GetPathName()); J->WriteValue(TEXT("operation"),R.Operation); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("submitted"),!R.bDryRun); J->WriteValue(TEXT("registration_state_verified"),false); J->WriteValue(TEXT("scope"),TEXT("Native world registration request; auto-registration may register actors again. No persistent component/default changes.")); J->WriteObjectEnd(); J->Close(); return Result;
}

FString PerceptionUtils::InspectSources(const FString& Search,int32 Limit)
{
 auto* World=NavigationWorldUtils::Resolve(TEXT("editor")); if(!IsInGameThread() || !IsValid(World) || World->WorldType!=EWorldType::Editor || Search.Len()>128 || Limit<1 || Limit>256) throw std::runtime_error("Source inspection requires editor world and bounded search/limit");
 TArray<UAIPerceptionStimuliSourceComponent*> Sources; for(TObjectIterator<UAIPerceptionStimuliSourceComponent> It;It;++It) if(IsValid(*It) && !It->IsTemplate() && It->GetWorld()==World && It->GetOwner() && (Search.IsEmpty() || It->GetPathName().Contains(Search))) Sources.Add(*It); Sources.Sort([](const auto& A,const auto& B) { return A.GetPathName()<B.GetPathName(); });
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("total"),Sources.Num()); J->WriteValue(TEXT("truncated"),Sources.Num()>Limit); J->WriteArrayStart(TEXT("sources")); for(int32 Index=0;Index<FMath::Min(Limit,Sources.Num());++Index) { auto* C=Sources[Index]; auto* Auto=FindFProperty<FBoolProperty>(C->GetClass(),TEXT("bAutoRegisterAsSource")); auto* Senses=FindFProperty<FArrayProperty>(C->GetClass(),TEXT("RegisterAsSourceForSenses")); J->WriteObjectStart(); J->WriteValue(TEXT("component_path"),C->GetPathName()); J->WriteValue(TEXT("owner_path"),C->GetOwner()->GetPathName()); J->WriteValue(TEXT("auto_register"),Auto && Auto->GetPropertyValue_InContainer(C)); J->WriteArrayStart(TEXT("sense_classes")); if(Senses) { FScriptArrayHelper Helper(Senses,Senses->ContainerPtrToValuePtr<void>(C)); if(auto* Inner=CastField<FClassProperty>(Senses->Inner)) for(int32 Entry=0;Entry<FMath::Min(Helper.Num(),64);++Entry) J->WriteValue(GetPathNameSafe(Inner->GetObjectPropertyValue(Helper.GetRawPtr(Entry)))); } J->WriteArrayEnd(); J->WriteValue(TEXT("package"),C->GetOwner()->GetPackage()->GetName()); J->WriteValue(TEXT("dirty"),C->GetOwner()->GetPackage()->IsDirty()); J->WriteObjectEnd(); } J->WriteArrayEnd(); J->WriteObjectEnd(); J->Close(); return Result;
}
FString PerceptionUtils::ConfigureSource(const FPerceptionReq& R)
{
 auto* World=NavigationWorldUtils::Resolve(TEXT("editor")); if(!IsInGameThread() || !GEditor || GEditor->PlayWorld || !IsValid(World) || World->WorldType!=EWorldType::Editor || R.ComponentPath.IsEmpty() || R.ComponentPath.Len()>2048 || R.SenseClasses.Num()>64) throw std::runtime_error("Source configuration requires stopped PIE, editor world and bounded explicit component/senses");
 auto* C=FindObject<UAIPerceptionStimuliSourceComponent>(nullptr,*R.ComponentPath); if(!IsValid(C) || C->IsTemplate() || C->GetWorld()!=World || !C->GetOwner() || !C->GetOwner()->GetPackage()->GetName().StartsWith(TEXT("/Game/")) || C->GetOwner()->HasAnyFlags(RF_Transient)) throw std::runtime_error("Source configuration requires placed /Game editor component");
 auto* Auto=FindFProperty<FBoolProperty>(C->GetClass(),TEXT("bAutoRegisterAsSource")); auto* Senses=FindFProperty<FArrayProperty>(C->GetClass(),TEXT("RegisterAsSourceForSenses")); auto* Inner=Senses ? CastField<FClassProperty>(Senses->Inner) : nullptr; if(!Auto || !Inner) throw std::runtime_error("Unsupported native stimuli-source layout");
 TArray<UClass*> Classes; for(const auto& Path:R.SenseClasses) { if(Path.Len()>1024) throw std::runtime_error("Sense class path too long"); auto* Class=FindObject<UClass>(nullptr,*Path); if(!Class || !Class->IsChildOf(UAISense::StaticClass()) || Class->HasAnyClassFlags(CLASS_Abstract|CLASS_Deprecated|CLASS_NewerVersionExists) || Classes.Contains(Class)) throw std::runtime_error("Sense classes must be unique loaded concrete native senses"); Classes.Add(Class); }
 FScriptArrayHelper Current(Senses,Senses->ContainerPtrToValuePtr<void>(C)); bool Changed=Auto->GetPropertyValue_InContainer(C)!=R.bEnabled || Current.Num()!=Classes.Num(); for(int32 Index=0;Index<FMath::Min(Current.Num(),Classes.Num());++Index) Changed|=Inner->GetObjectPropertyValue(Current.GetRawPtr(Index))!=Classes[Index]; if(Changed && !R.bConfirm) throw std::runtime_error("Replacing source registration settings requires confirmation");
 if(Changed && !R.bDryRun) { FScopedTransaction Transaction(FText::FromString(TEXT("MCP Configure Perception Source"))); C->GetOwner()->Modify(); C->SetFlags(RF_Transactional); C->Modify(); Auto->SetPropertyValue_InContainer(C,R.bEnabled); Current.EmptyValues(); Current.AddValues(Classes.Num()); for(int32 Index=0;Index<Classes.Num();++Index) Inner->SetObjectPropertyValue(Current.GetRawPtr(Index),Classes[Index]); FPropertyChangedEvent Event(Senses,EPropertyChangeType::ValueSet); C->PostEditChangeProperty(Event); C->MarkPackageDirty(); }
 bool Saved=false; if(R.bSave && !R.bDryRun) { Saved=UEditorLoadingAndSavingUtils::SavePackages({C->GetOwner()->GetPackage()},false); if(!Saved) throw std::runtime_error("Source settings applied but package save failed"); } FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("component_path"),R.ComponentPath); J->WriteValue(TEXT("would_change"),Changed); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("saved"),Saved); J->WriteObjectEnd(); J->Close(); return Result;
}
